import{_ as a,o as e,c as i,ag as n}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"本地配置文件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/settings/local-file-config.md","filePath":"zh/settings/local-file-config.md","lastUpdated":1783295281000}'),t={name:"zh/settings/local-file-config.md"};function l(p,s,o,d,r,c){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="本地配置文件" tabindex="-1">本地配置文件 <a class="header-anchor" href="#本地配置文件" aria-label="Permalink to &quot;本地配置文件&quot;">​</a></h1><p>EasyYapi 使用 <code>.easy.api.config</code> 文件作为本地配置文件。从 EasyYapi 3.0 起推荐使用 <a href="./rule-authoring#基于文件夹的规则文件"><code>.easyapi/</code> 文件夹模型</a>，<code>.easyapi/</code> 中的每个常规文件都会被自动加载。下方旧的 <code>.easy.api.config*</code> 文件仍会被读取以保持向后兼容。</p><h2 id="文件位置" tabindex="-1">文件位置 <a class="header-anchor" href="#文件位置" aria-label="Permalink to &quot;文件位置&quot;">​</a></h2><p>规则文件基于 <strong>IntelliJ 工程根目录</strong>（你在 IDE 中打开的文件夹，即 <code>project.basePath</code>）解析。发现过程<strong>不会</strong>向下递归到子目录，因此当父目录被 作为工程打开时，放在嵌套模块文件夹中的配置文件<strong>不会</strong>被加载。</p><blockquote><p><strong>多模块工程注意：</strong> 不存在按模块划分的配置层。若你将 <code>your-project/</code> 作为工程 打开，只会读取 <code>your-project/</code> 及其<strong>祖先</strong>目录下的 <code>.easy.api.config</code> / <code>.easyapi/</code>。若希望某个模块拥有独立规则，请将该模块文件夹单独作为 IntelliJ 工程打开，或将所有规则统一放在共享的 <code>&lt;project&gt;/.easyapi/</code> 文件夹中。</p></blockquote><h3 id="项目根目录" tabindex="-1">项目根目录 <a class="header-anchor" href="#项目根目录" aria-label="Permalink to &quot;项目根目录&quot;">​</a></h3><p>你在 IDE 中打开的文件夹：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>├── .easy.api.config</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>└── pom.xml</span></span></code></pre></div><p>旧版的 <code>.easy.api.config[.properties|.yml|.yaml]</code> 文件还会从工程根目录<strong>向上</strong> 查找祖先目录（例如多个工程共享的父目录中的配置）。</p><h3 id="_3-0-文件夹模型-推荐" tabindex="-1">3.0+ 文件夹模型（推荐） <a class="header-anchor" href="#_3-0-文件夹模型-推荐" aria-label="Permalink to &quot;3.0+ 文件夹模型（推荐）&quot;">​</a></h3><p>在 <code>.easyapi/</code> 文件夹中放置任意数量的 <code>.rules</code>（或 <code>.properties</code>）文件。每个常规文件都会被加载——无需维护文件列表。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>├── .easyapi/</span></span>
<span class="line"><span>│   ├── naming.rules</span></span>
<span class="line"><span>│   ├── security.rules</span></span>
<span class="line"><span>│   └── postman.rules</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>└── pom.xml</span></span></code></pre></div><p>全局范围同样适用此模型：<code>~/.easyapi/*.rules</code> 会为本机所有项目加载。可在 <strong>Settings → EasyApi → Rules</strong>（Project / Global / Remote 子标签页）中以可视化方式管理文件。</p><h2 id="文件格式" tabindex="-1">文件格式 <a class="header-anchor" href="#文件格式" aria-label="Permalink to &quot;文件格式&quot;">​</a></h2><p>配置文件使用 <code>key=value</code> 格式：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 注释以 # 开头</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># API 名称规则</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">api.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#name</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 字段忽略规则</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">field.ignore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.hasAnn(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.fasterxml.jackson.annotation.JsonIgnore&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 类型转换</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">json.rule.convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:it.type().name()==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;java.util.Date&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =&gt; java.lang.String</span></span></code></pre></div><h2 id="配置合并" tabindex="-1">配置合并 <a class="header-anchor" href="#配置合并" aria-label="Permalink to &quot;配置合并&quot;">​</a></h2><p>配置由多个来源按优先级合并。在同一来源内，<code>.easyapi/</code> 中的文件按文件名排序依次 读取并追加。对于同一个 key，高优先级来源会覆盖低优先级来源。</p><table tabindex="0"><thead><tr><th style="text-align:center;">优先级</th><th>来源</th><th>加载位置</th></tr></thead><tbody><tr><td style="text-align:center;">4</td><td><strong>工程规则</strong></td><td><code>&lt;project&gt;/.easyapi/*</code>（全部常规文件）+ 从 <code>&lt;project&gt;</code> 向上查找的旧版 <code>.easy.api.config*</code></td></tr><tr><td style="text-align:center;">3</td><td>扩展规则</td><td>内置框架预设（Spring、Jackson、Validation、Swagger……），可在 Settings → Extensions 中开关</td></tr><tr><td style="text-align:center;">3</td><td>远程规则</td><td>来自 <code>remote.url</code> 的 URL（Settings → Rules → Remote）</td></tr><tr><td style="text-align:center;">2</td><td>全局规则</td><td><code>~/.easyapi/*</code>（全部常规文件）</td></tr></tbody></table><p>工程规则优先级最高，全局规则为最低的兜底层。不存在单独的“模块级”配置层。</p><h2 id="包含其他配置文件" tabindex="-1">包含其他配置文件 <a class="header-anchor" href="#包含其他配置文件" aria-label="Permalink to &quot;包含其他配置文件&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">v3.2.0 新增</p><p><code>###include &lt;path-or-url&gt;</code> 指令（自 v3.2.0 起，#1410）允许规则文件引入其他本地文件或远程 URL。这是组合配置的<strong>首选</strong>方式；旧版的 <code>properties.additional</code> key 保留向后兼容，行为完全一致。</p></div><p>在规则文件中独占一行写入 <code>###include</code> 指令即可引入另一个配置源：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 相对当前文件目录加载共享规则文件</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###include ./shared/security.rules</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 绝对路径</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###include /etc/easyapi/team.rules</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 家目录相对路径</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###include ~/easyapi/personal.rules</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 远程 URL（http/https）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###include https://raw.githubusercontent.com/org/repo/main/easyapi/common.rules</span></span></code></pre></div><h3 id="行为说明" tabindex="-1">行为说明 <a class="header-anchor" href="#行为说明" aria-label="Permalink to &quot;行为说明&quot;">​</a></h3><ul><li>指令必须独占一行。参数为要加载的路径或 URL（自动去除首尾空白）。</li><li><strong>本地路径</strong>相对于<em>包含该指令的文件所在目录</em>解析（或 <code>~/</code> 家目录，或绝对路径）。<strong>远程 URL</strong>（<code>http://</code> / <code>https://</code>）通过带缓存的资源解析器拉取。</li><li>被包含的文件使用<strong>调用方的指令状态</strong>解析，因此 include 之前生效的 <code>###set</code> 选项会延续到被包含文件中（例如 <code>###set ignoreUnresolved = true</code> 会被继承）。</li><li>被包含文件中的相对路径相对于<em>被包含文件自身</em>的目录解析（远程 include 则相对于同一 host）。</li><li>若资源无法解析，EasyYapi 会抛出错误——除非在 include 之前用 <code>###set ignoreNotFoundFile = true</code> 静默：</li></ul><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可选 include：文件缺失时静默跳过</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###set ignoreNotFoundFile = true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###include ./optional/local-overrides.rules</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###set ignoreNotFoundFile = false</span></span></code></pre></div><h3 id="旧版形式-properties-additional" tabindex="-1">旧版形式：<code>properties.additional</code> <a class="header-anchor" href="#旧版形式-properties-additional" aria-label="Permalink to &quot;旧版形式：\`properties.additional\`&quot;">​</a></h3><p>旧版的 <code>properties.additional=&lt;path-or-url&gt;</code> key（每行一条）是 <code>###include</code> 的旧版等价物，行为完全一致——相同的解析规则、相同的指令状态继承、相同的 <code>ignoreNotFoundFile</code> 门控。推荐使用 <code>###include</code> 以获得更好的可读性；<code>properties.additional</code> 继续支持以保持现有配置可用。</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 旧版形式（仍受支持，行为与 ###include 完全一致）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">properties.additional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=./shared/security.rules</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">properties.additional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://raw.githubusercontent.com/org/repo/main/easyapi/common.rules</span></span></code></pre></div>`,30)])])}const k=a(t,[["render",l]]);export{g as __pageData,k as default};
